/// Editable settings shared by bunny_db_search_create and bunny_db_search_update
/// (M9.7.2) -- kept as one struct instead of ever-more positional bool/int
/// params, since this set has grown with nearly every sub-milestone that's
/// touched searches.
final class bunny_db_search_options_t extends ffi.Struct {
  /// queue a favorite for every post this search finds during sync
  @ffi.Bool()
  external bool auto_favorite;

  /// Inkbunny favorite level (1-3); ignored by e621, which has no stars concept
  @ffi.Int()
  external int auto_favorite_stars;

  /// e621 only -- queue an upvote for every post this search finds during sync
  @ffi.Bool()
  external bool auto_upvote;

  /// When true, interval_hours is ignored for scheduling -- the effective
  /// interval is whatever bunny_db_settings_get_default_interval_hours()
  /// currently returns, re-resolved on every due-check rather than frozen
  /// at creation/edit time. interval_hours itself is still stored (kept at
  /// whatever it last was) so toggling this back off doesn't lose the
  /// previous explicit value.
  @ffi.Bool()
  external bool uses_default_interval;

  /// INKBUNNY_SEARCH_IN_* bits; 0 = default (keywords)
  @ffi.Int()
  external int inkbunny_search_in_mask;

  /// 0 = or, 1 = and
  @ffi.Int()
  external int inkbunny_field_join_type;

  /// 0 = and, 1 = or, 2 = exact
  @ffi.Int()
  external int inkbunny_string_join_type;

  /// NULL = unset
  external ffi.Pointer<ffi.Char> inkbunny_username;

  /// bit (type_id - 1); 0 = every type
  @ffi.Int()
  external int inkbunny_submission_type_mask;

  /// 0 = no limit
  @ffi.Int()
  external int inkbunny_days_limit;

  /// NULL = default (create_datetime)
  external ffi.Pointer<ffi.Char> inkbunny_order_by;

  @ffi.Bool()
  external bool inkbunny_random;

  /// 0 = both, 1 = no, 2 = only
  @ffi.Int()
  external int inkbunny_scraps;
}

